const body = $input.first().json.body || $input.first().json;

const cnaeCodes = body.cnaeCodes || [];
const states = body.states || [];
const capitalMin = parseInt(body.capitalMin) || 0;
const capitalMax = parseInt(body.capitalMax) || 10000000;
const excludeMei = body.excludeMei !== false;
const targetCount = parseInt(body.targetCount) || 150;

if (cnaeCodes.length === 0) {
  throw new Error('Nenhum codigo CNAE informado.');
}

return [{
  json: {
    cnaeCodes,
    states,
    capitalMin,
    capitalMax,
    excludeMei,
    targetCount,
    totalCnaes: cnaeCodes.length,
    currentCnaeIndex: 0,
    currentPage: 1,
    allCompanies: [],
    seenCnpjs: []
  }
}];

const data = $input.first().json;
const cnae = data.cnaeCodes[data.currentCnaeIndex];

const payload = {
  query: {
    termo: [],
    atividade_principal: [cnae],
    natureza_juridica: [],
    uf: data.states.length > 0 ? data.states : [],
    municipio: [],
    situacao_cadastral: 'ATIVA'
  },
  range_query: {
    capital_social: { gte: data.capitalMin, lte: data.capitalMax }
  },
  extras: {
    somente_mei: false,
    excluir_mei: data.excludeMei,
    com_email: false,
    incluir_atividade_secundaria: false,
    com_contato_telefonico: true
  },
  page: data.currentPage
};

return [{ json: { ...data, currentCnae: cnae, requestPayload: payload } }];

// Buscar CNPJs via Apify Web Scraper (contorna Cloudflare da Casa dos Dados)
const data = $input.first().json;
const payload = data.requestPayload;
const APIFY_TOKEN = 'apify_api_IcL12FYoB2JQf0NdZ89DrAUvoUQVSA2xh8sf';

try {
  // Iniciar Apify actor que faz POST via browser headless
  const startRes = await fetch(
    'https://api.apify.com/v2/acts/apify~web-scraper/runs?token=' + APIFY_TOKEN,
    {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        startUrls: [{ url: 'https://casadosdados.com.br/solucao/cnpj' }],
        pageFunction: `async function pageFunction(context) {
          const payload = ${JSON.stringify(payload)};
          const res = await fetch('https://api.casadosdados.com.br/v2/public/cnpj/search', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          });
          if (!res.ok) return { error: res.status, data: { cnpj: [] } };
          return await res.json();
        }`,
        proxyConfiguration: { useApifyProxy: true },
        maxRequestsPerCrawl: 1
      })
    }
  );
  const run = await startRes.json();
  const runId = run.data.id;

  // Poll ate completar
  let status = 'RUNNING';
  let datasetId = '';
  for (let i = 0; i < 30; i++) {
    await new Promise(r => setTimeout(r, 3000));
    const pollRes = await fetch('https://api.apify.com/v2/acts/apify~web-scraper/runs/' + runId + '?token=' + APIFY_TOKEN);
    const pollData = await pollRes.json();
    status = pollData.data.status;
    datasetId = pollData.data.defaultDatasetId;
    if (status === 'SUCCEEDED' || status === 'FAILED' || status === 'ABORTED') break;
  }

  if (status !== 'SUCCEEDED') return [{ json: { data: { cnpj: [] } } }];

  // Pegar resultado
  const itemsRes = await fetch('https://api.apify.com/v2/datasets/' + datasetId + '/items?token=' + APIFY_TOKEN);
  const items = await itemsRes.json();
  return [{ json: items[0] || { data: { cnpj: [] } } }];
} catch (err) {
  return [{ json: { data: { cnpj: [] } } }];
}

const prev = $('3. Montar Query CNAE').first().json;
const response = $input.first().json;

const companies = response?.data?.cnpj || [];
const allCompanies = [...(prev.allCompanies || [])];
const seenCnpjs = new Set(prev.seenCnpjs || []);

let newCount = 0;
for (const c of companies) {
  const cleanCnpj = (c.cnpj || '').replace(/\D/g, '');
  if (!cleanCnpj || seenCnpjs.has(cleanCnpj)) continue;
  seenCnpjs.add(cleanCnpj);
  newCount++;
  allCompanies.push({
    cnpj: cleanCnpj,
    razao_social: c.razao_social || '',
    nome_fantasia: c.nome_fantasia || '',
    cnae_fiscal_descricao: c.cnae_fiscal_descricao || '',
    cnae_fiscal: c.cnae_fiscal || '',
    uf: c.uf || '',
    municipio: c.municipio || '',
    logradouro: c.logradouro || '',
    numero: c.numero || '',
    bairro: c.bairro || '',
    capital_social: c.capital_social || 0,
    porte: c.porte || '',
    data_inicio_atividade: c.data_inicio_atividade || '',
    telefone1: c.ddd_telefone_1 || c.telefone1 || '',
    telefone2: c.ddd_telefone_2 || c.telefone2 || '',
    email: c.correio_eletronico || c.email || '',
    qsa: (c.qsa || []).map(s => ({ nome_socio: s.nome_socio || s.nome || '', qualificacao_socio: s.qualificacao_socio || s.qual || '' }))
  });
}

const hasMorePages = newCount > 0 && prev.currentPage < 10;
const needsMore = allCompanies.length < prev.targetCount;
const hasMoreCnaes = prev.currentCnaeIndex < prev.totalCnaes - 1;

let nextPage = prev.currentPage;
let nextCnaeIndex = prev.currentCnaeIndex;
let continueLoop = false;

if (needsMore && hasMorePages) {
  nextPage = prev.currentPage + 1;
  continueLoop = true;
} else if (needsMore && hasMoreCnaes) {
  nextCnaeIndex = prev.currentCnaeIndex + 1;
  nextPage = 1;
  continueLoop = true;
}

return [{ json: { ...prev, allCompanies, seenCnpjs: Array.from(seenCnpjs), currentPage: nextPage, currentCnaeIndex: nextCnaeIndex, continueLoop, totalFound: allCompanies.length } }];

// Enriquecer cada CNPJ com OpenCNPJ para socios e telefones
const data = $input.first().json;
const companies = data.allCompanies || [];

for (let i = 0; i < companies.length; i++) {
  const c = companies[i];
  try {
    const res = await fetch('https://api.opencnpj.org/' + c.cnpj);
    if (res.ok) {
      const d = await res.json();
      const socios = (d.qsa || []).map(s => ({ nome_socio: s.nome_socio || s.nome || '', qualificacao_socio: s.qualificacao_socio || s.qual || '' }));
      const phones = [d.telefone1, d.telefone2, d.ddd_telefone_1, d.ddd_telefone_2, d.telefone].filter(Boolean).flatMap(p => p.split(/[\/;,]/)).map(p => p.trim().replace(/\D/g, '')).filter(p => p.length >= 10);
      if (socios.length > 0) c.qsa = socios;
      if (phones[0]) c.telefone1 = phones[0];
      if (phones[1]) c.telefone2 = phones[1];
      c.email = d.email || d.correio_eletronico || c.email;
      c.capital_social = d.capital_social || c.capital_social;
      c.nome_fantasia = d.nome_fantasia || c.nome_fantasia;
    }
  } catch {}
  if (i < companies.length - 1) await new Promise(r => setTimeout(r, 200));
}

return [{ json: { ...data, allCompanies: companies } }];

// Classificar telefones, extrair decisor, preparar itens individuais para Airtable
const data = $input.first().json;
const companies = data.allCompanies || [];

function classifyPhone(phone) {
  const d = phone.replace(/\D/g, '');
  const w = d.startsWith('55') ? d.slice(2) : d;
  if (w.length === 11 && w[2] === '9') return 'mobile';
  if (w.length === 10 && w[2] === '9') return 'mobile';
  return 'landline';
}

function formatPhone(phone) {
  let d = phone.replace(/\D/g, '').replace(/^0+/, '');
  const w = d.startsWith('55') ? d.slice(2) : d;
  if (w.length === 10 && w[2] === '9') {
    d = w.slice(0, 2) + '9' + w.slice(2);
    return '55' + d;
  }
  return d.length >= 10 ? (d.startsWith('55') ? d : '55' + d) : d;
}

// Mapear cada empresa como item individual para o SplitInBatches
const items = companies.map(c => {
  const socios = c.qsa || [];
  const decisor = socios.find(s => (s.qualificacao_socio||'').toLowerCase().includes('administrador') || (s.qualificacao_socio||'').toLowerCase().includes('diretor') || (s.qualificacao_socio||'').toLowerCase().includes('presidente')) || socios[0];

  const phones = [c.telefone1, c.telefone2].filter(Boolean).flatMap(p => p.split(/[\/;,]/)).map(p => p.trim().replace(/\D/g, '')).filter(p => p.length >= 10);
  const mobile = phones.find(p => classifyPhone(p) === 'mobile');
  const whatsapp = mobile ? formatPhone(mobile) : '';
  const mainPhone = phones[0] ? formatPhone(phones[0]) : '';

  const capital = c.capital_social || 0;
  const tier = capital >= 830000 ? 'Medium=' : capital >= 200000 ? 'Medium-' : capital >= 100000 ? 'Small' : 'Micro+';

  return {
    json: {
      companyName: c.razao_social,
      tradeName: c.nome_fantasia,
      cnpj: c.cnpj,
      segment: c.cnae_fiscal_descricao,
      tier: tier,
      status: 'Novo',
      score: 0,
      temperatura: 'Frio',
      address: [c.logradouro, c.numero, c.bairro].filter(Boolean).join(', '),
      city: c.municipio,
      state: c.uf,
      capitalSocial: capital,
      rfPhone: mainPhone,
      rfEmail: c.email,
      cnaePrimary: c.cnae_fiscal,
      foundingDate: c.data_inicio_atividade,
      enrichmentStatus: 'basic',
      partners: JSON.stringify(c.qsa || []),
      // Campos para Contact
      _decisorName: decisor?.nome_socio || '',
      _decisorRole: decisor?.qualificacao_socio || '',
      _whatsapp: whatsapp,
      _hasWhatsapp: !!whatsapp,
      _hasDecisor: !!(decisor?.nome_socio)
    }
  };
});

return items;

